import{_ as i,o as t,c as a,a5 as s}from"./chunks/framework.Cx-mnQW-.js";const c=JSON.parse('{"title":"Linux setup","description":"","frontmatter":{"title":"Linux setup"},"headers":[],"relativePath":"guide/setup/linux.md","filePath":"guide/setup/linux.md","lastUpdated":1785753275000}'),o={name:"guide/setup/linux.md"};function l(n,e,d,r,u,p){return t(),a("div",null,[...e[0]||(e[0]=[s(`<h1 id="linux-setup" tabindex="-1">Linux setup <a class="header-anchor" href="#linux-setup" aria-label="Permalink to &quot;Linux setup&quot;">​</a></h1><p>Linux desktop widgets use the same <strong>embedded</strong> webview path as <a href="/tauri-plugin-widgets/guide/setup/desktop">Desktop webview</a>: <code>createWidgetWindow</code> without <code>url</code> (no <code>widget.html</code> copy). Extra Linux behavior is window pinning.</p><h2 id="how-it-works" tabindex="-1">How it works <a class="header-anchor" href="#how-it-works" aria-label="Permalink to &quot;How it works&quot;">​</a></h2><ol><li><code>setWidgetConfig</code> writes IR into the desktop file store for <code>(group, widgetId)</code>.</li><li><code>createWidgetWindow</code> opens a frameless Tauri webview on the <code>widgetview</code> protocol.</li><li>With Cargo feature <code>linux</code> (<strong>default</strong>), the plugin sets X11 <code>_NET_WM_WINDOW_TYPE_DESKTOP</code> so the window behaves like a desktop pin.</li><li>Optional feature <code>layer-shell</code> remaps the window onto gtk-layer-shell <strong>Background</strong> on Wayland.</li></ol><h2 id="setup" tabindex="-1">Setup <a class="header-anchor" href="#setup" aria-label="Permalink to &quot;Setup&quot;">​</a></h2><ol><li>Keep default features, or enable explicitly:</li></ol><div class="language-toml vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">toml</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">tauri-plugin-widgets = { version = </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;0.5&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, features = [</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;linux&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">] }</span></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># Wayland:</span></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># tauri-plugin-widgets = { version = &quot;0.5&quot;, features = [&quot;linux&quot;, &quot;layer-shell&quot;] }</span></span></code></pre></div><ol start="2"><li>Allow the window label in capabilities (<code>windows</code> + <code>widgets:default</code>) — <a href="/tauri-plugin-widgets/guide/install#permissions">Install</a>.</li><li>Call <code>createWidgetWindow</code> as in <a href="/tauri-plugin-widgets/guide/first-widget">First widget</a>.</li></ol><p>Contributor harness / debugging: <a href="/tauri-plugin-widgets/contributing/linux-harness">Linux harness</a>.</p><h2 id="when-it-fails" tabindex="-1">When it fails <a class="header-anchor" href="#when-it-fails" aria-label="Permalink to &quot;When it fails&quot;">​</a></h2><ul><li>Enable the <code>linux</code> feature for X11 DESKTOP pinning (<code>default-features = false</code> drops it).</li><li>Wayland: try <code>layer-shell</code>; plain X11 hints will not apply.</li><li>See <a href="/tauri-plugin-widgets/contributing/linux-harness">Linux harness</a> for debugging pinned windows.</li></ul><p>More symptoms: <a href="/tauri-plugin-widgets/guide/troubleshooting">Troubleshooting index</a>.</p>`,12)])])}const g=i(o,[["render",l]]);export{c as __pageData,g as default};
